WITH cleaned AS (SELECT id, account_id, amount, txn_time, merchant, is_flagged, UPPER(txn_type) AS txn_type_upper, COALESCE(merchant, 'DIRECT') AS resolved_merchant FROM transactions WHERE txn_time > TIMESTAMP '2023-10-14 00:00:00') SELECT id, amount, txn_time, is_flagged, txn_type_upper, resolved_merchant FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY merchant ORDER BY txn_time DESC, id) AS rank_in_group FROM cleaned) x WHERE rank_in_group = 1
